{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 10,
      "text_ar": "هوذا فجأة صرخت صرخة عظيمة ومخفية جدا حتى اهتزت الأرض للصوت.",
      "verse": 26
    },
    {
      "chapter": 10,
      "text_ar": "نظرت وإذا بالمرأة لا تظهر لي بعد بل كانت هناك مدينة مبنية وموضع ظهر من أساسات عظيمة، فحينئذ خفت وصرخت بصوت عالٍ:",
      "verse": 27
    },
    {
      "chapter": 10,
      "text_ar": "أين الملاك أوريئيل الذي جاء إليّ في البدء؟ لأنه جعلني أقع في هذه الغشية العظيمة وصارت نهايتي فساداً وصلاتي عاراً!",
      "verse": 28
    },
    {
      "chapter": 10,
      "text_ar": "وبينما كنت أتكلم بهذا الكلام هوذا الملاك الذي أتى إليّ في البدء جاء ونظر إليّ.",
      "verse": 29
    },
    {
      "chapter": 10,
      "text_ar": "وهوذا كنت مضطجعاً كالميت ونُزع فهمي مني، فأمسكني بيدي اليمنى وعزاني وأقامني على قدمي وقال لي:",
      "verse": 30
    }
  ]
}
